use vstd::prelude::*;

verus! {
    // Given a vector `a`, return a new vector `a_rev` which is the reverse of `a`.
    // No preconditions are needed: `a` may be empty or contain any i32 values.
    //
    // Postcondition:
    //   1. The length of the result equals the length of `a`.
    //   2. For every index `i` in `0..a.len()`, we have
    //        result[i] == a[a.len() - 1 - i].
    fn reverse(a: &Vec<i32>) -> Vec<i32>
        ensures |res: Vec<i32>|
            res.len() == a.len() &&
            forall |i: usize| i < a.len() ==> res[i] == a[a.len() - 1 - i]
    {
        let n = a.len();
        let mut a_rev: Vec<i32> = Vec::new();
        let mut i: usize = 0;

        // We build `a_rev` by pushing elements from the end of `a` to the front.
        // Loop invariants:
        //   1. 0 <= i <= n.
        //   2. a_rev.len() == i.
        //   3. For all j < i, a_rev[j] == a[n - 1 - j].
        // We decrease on `n - i` to prove termination.
        while i < n
            invariant i <= n
            invariant a_rev.len() == i
            invariant forall |j: usize| j < i ==> a_rev[j] == a[n - 1 - j]
            decreases n - i
        {
            let x = a[n - 1 - i];
            a_rev.push(x);
            i += 1;
        }

        a_rev
    }
}